// Entry point (the chat). Reads the goal, the URLs and the alert destination from the message,
// continues an open question ("which endpoint?") from the same chat session, and counts runs per day.
// $json is the chat message plus the values of "Settings".
const PUBLIC_URL = $json.PUBLIC_URL || '';
const PENDING_QUESTION_LIFETIME_MS = (Number($json.PENDING_QUESTION_MINUTES) || 30) * 60 * 1000;
const DAILY_RUNS_PER_CHAT = Number($json.DAILY_RUNS_PER_CHAT) || 0;   // 0 = no limit
const DAILY_RUNS_TOTAL = Number($json.DAILY_RUNS_TOTAL) || 0;         // 0 = no limit
const URL_PATTERN = /https?:\/\/[^\s'\"<>)]+/g;
const EMAIL_PATTERN = /[\w.+-]+@[\w-]+(\.[\w-]+)+/;
const ALERT_WEBHOOK_PATTERN = /hooks\.slack\.com|webhook\.site|discord(app)?\.com\/api\/webhooks|webhook\.office\.com|chat\.googleapis\.com/;
const SLACK_CHANNEL_PATTERN = /#([a-z0-9][\w-]{0,79})/i;

const input = $json;
const baseUrl = findBaseUrl();

return [{ json: readChatMessage() }];

function readChatMessage() {
  const text = String(input.chatInput || '').trim();
  const urls = findUrls(text);
  const alertWebhookUrl = urls.find((url) => isAlertWebhook(url)) || null;
  const targetUrl = urls.find((url) => !isAlertWebhook(url)) || null;

  let goal = text;
  if (alertWebhookUrl) {
    goal = text.split(alertWebhookUrl).join('').replace(/\s+/g, ' ').trim();
  }

  const pendingQuestion = getPendingQuestion(input.sessionId);
  if (pendingQuestion && urls.length > 0 && isMostlyUrls(text)) {
    goal = pendingQuestion.goal;
  }

  let continuedFrom = null;
  if (pendingQuestion && goal === pendingQuestion.goal && goal !== text) {
    continuedFrom = pendingQuestion.goal;
  }

  let slackChannel = null;
  if (!alertWebhookUrl) {
    slackChannel = findSlackChannel(text);
  }

  return {
    channel: 'chat',
    sessionId: input.sessionId,
    base: baseUrl,
    email: findEmail(text),
    slackChannel,
    body: { goal, targetUrl: targetUrl || undefined, alertWebhookUrl: alertWebhookUrl || undefined },
    continuedFrom,
    pendingQuestionLifetimeMs: PENDING_QUESTION_LIFETIME_MS,
    limitReached: goal.trim().length > 5 ? countRun(input.sessionId) : null,
  };
}

function countRun(sessionId) {
  // Counts builds per chat session and in total, per UTC day. Kept in static data, which n8n saves only for
  // production runs (the public chat), not for manual test runs.
  const storage = $getWorkflowStaticData('global');
  const today = new Date().toISOString().slice(0, 10);

  if (!storage.usage || storage.usage.day !== today) {
    storage.usage = { day: today, total: 0, bySession: {} };
  }

  const usage = storage.usage;
  const key = String(sessionId || 'unknown');

  if (DAILY_RUNS_TOTAL && usage.total >= DAILY_RUNS_TOTAL) {
    return 'This Alchemist has reached its limit of ' + DAILY_RUNS_TOTAL + ' builds for today. Please try again tomorrow.';
  }
  if (DAILY_RUNS_PER_CHAT && (usage.bySession[key] || 0) >= DAILY_RUNS_PER_CHAT) {
    return 'This chat has reached its limit of ' + DAILY_RUNS_PER_CHAT + ' builds for today. Please try again tomorrow.';
  }

  usage.total += 1;
  usage.bySession[key] = (usage.bySession[key] || 0) + 1;
  return null;
}

function findBaseUrl() {
  if (PUBLIC_URL) return PUBLIC_URL.replace(/\/+$/, '');
  const originFromN8n = getOrigin($execution.resumeUrl);
  if (originFromN8n) return originFromN8n;
  const host = input.headers?.host;
  if (!host) return null;
  const isLocalHost = /^(localhost|127\.|\[::1\])/.test(host);
  const defaultProtocol = isLocalHost ? 'http' : 'https';
  const protocol = String(input.headers['x-forwarded-proto'] || defaultProtocol).split(',')[0].trim();
  return protocol + '://' + host;
}

function getOrigin(url) {
  const match = String(url || '').match(/^(https?:\/\/[^/?#]+)/i);
  return match ? match[1] : null;
}

function getPendingQuestion(sessionId) {
  const storage = $getWorkflowStaticData('global');
  const pendingQuestions = storage.pending || {};
  const question = pendingQuestions[sessionId];
  if (!question) return null;
  const isFresh = Date.now() - question.ts < PENDING_QUESTION_LIFETIME_MS;
  if (!isFresh) return null;
  return question;
}

function findUrls(text) {
  const matches = text.match(URL_PATTERN) || [];
  return matches.map((url) => url.replace(/[.,;:!?]+$/, ''));
}

function isAlertWebhook(url) {
  return ALERT_WEBHOOK_PATTERN.test(url);
}

function isMostlyUrls(text) {
  const textWithoutUrls = text.replace(/https?:\/\/\S+/g, '');
  const lettersLeft = textWithoutUrls.replace(/[^a-z]/gi, '');
  return lettersLeft.length < 12;
}

function findEmail(text) {
  const match = text.match(EMAIL_PATTERN);
  if (!match) return null;
  return match[0];
}

function findSlackChannel(text) {
  if (!/\bslack\b/i.test(text)) return null;
  const match = text.match(SLACK_CHANNEL_PATTERN);
  if (!match) return null; 
  return '#' + match[1];
}

// Initialize Case
//
// Validates the request and builds the state object that travels through every section.
// - An over-limit or invalid request ends the run at once with a reply.
// - The test mock is only needed by monitors. If it is unreachable, the problem is stored in
//   state.mockProblem and "Decide Next Step" stops a monitor run. Blueprints are not affected.

const URL_PATTERN = /https?:\/\/[^\s'"<>)]+/;
const EXACT_EMAIL_PATTERN = /^[\w.+-]+@[\w-]+\.[\w.-]+$/;

const request = $('Read Request').first().json;
const settings = $('Settings').first().json;
const body = request.body || {};
const mockCheck = $json;

if (request.limitReached) {
  return finish(429, { status: 'limited', verdict: 'Daily limit reached', message: request.limitReached });
}
if (!isGoalValid(body)) {
  return finish(400, { status: 'error', message: 'Tell me in one sentence what you want automated.' });
}

const goal = String(body.goal).trim().slice(0, 4000);

// URLs the user gave us. The target can also be written inside the goal sentence.
const targetUrl = cleanUrl(body.targetUrl) || findUrlInText(goal);
const alertWebhookUrl = cleanUrl(body.alertWebhookUrl);

const mockIsDown = Boolean(mockCheck.error) || mockCheck.statusCode !== 200;
const mockProblem = mockIsDown
  ? {
      mockUrl: String(request.base) + '/webhook/alchemist-mock',
      checkResult: mockCheck.error ? String(mockCheck.error.message || mockCheck.error) : 'HTTP ' + mockCheck.statusCode,
    }
  : null;

// The state object is created here and carried through every section.
// The comments name the node that reads or updates each group of fields.
const state = {
  // The request
  goal,
  base: request.base, // URL of this n8n instance, used for links and for the mock
  userTargetUrl: publicOnly(targetUrl), // endpoint to watch (monitors only)
  userAlertWebhookUrl: publicOnly(alertWebhookUrl), // alert webhook (monitors only)
  privateUrls: [targetUrl, alertWebhookUrl].filter((url) => url && isPrivateHost(url)), // refused URLs, kept for the reply
  alertEmail: findExactEmail(request.email),
  alertSlackChannel: request.slackChannel || null,
  mockProblem, // set when the test mock is unreachable
  startedAt: new Date().toISOString(),

  // Copied from "Settings", because each section runs in its own execution
  config: {
    coreNodesVersion: String(settings.CORE_NODES_VERSION),
    aiNodesVersion: String(settings.AI_NODES_VERSION),
    timeBudgetMinutes: Number(settings.TIME_BUDGET_MINUTES) || 12,
  },

  // Understand step ("Validate Spec")
  spec: null, // the understood request, kind "monitor" or "blueprint"
  specAttempt: 0,
  specFeedback: '',

  // Build and repair loop ("Decide Next Step")
  attempt: 1,
  maxAttempts: clamp(Number(settings.MAX_ATTEMPTS) || 3, 1, 5),
  feedback: '', // what the next build attempt must fix
  previousWorkflow: null, // the draft being repaired
  history: [], // one entry per attempt
  lastStage: 'understand', // the section that ran last
  stop: null, // why the loop ended early (stuck, setup, harness, ...)

  // Monitors only
  best: null, // best test score so far
  regressed: null,
  triedUrl: null,
  smokeDetail: null,
  setupError: null,
  harnessError: null,

  // Blueprints only
  bestBlueprint: null, // best valid draft so far, always delivered at the end
  reviewRepairUsed: false, // a blueprint gets one review repair round
};

return [{ json: { done: false, stage: 'understand', state } }];

// ---------------------------------------------------------------------------
// Reply and input checks
// ---------------------------------------------------------------------------

function finish(httpStatus, replyBody) {
  return [{ json: { done: true, httpStatus, body: replyBody } }];
}

function isGoalValid(requestBody) {
  if (typeof requestBody.goal !== 'string') return false;
  return requestBody.goal.trim().length > 5;
}

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

// ---------------------------------------------------------------------------
// Reading URLs and emails from user input
// ---------------------------------------------------------------------------

// Returns the trimmed URL if it is a plain http(s) URL, otherwise null.
function cleanUrl(value) {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  return /^https?:\/\/[^\s'"]+$/i.test(trimmed) ? trimmed : null;
}

// Returns the first URL found in free text, without trailing punctuation, or null.
function findUrlInText(text) {
  const match = text.match(URL_PATTERN);
  if (!match) return null;
  return cleanUrl(match[0].replace(/[.,;:!?]+$/, ''));
}

// Returns the value only if the whole string is one email address, otherwise null.
function findExactEmail(value) {
  const match = String(value || '').trim().match(EXACT_EMAIL_PATTERN);
  return match ? match[0] : null;
}

// ---------------------------------------------------------------------------
// Private address check (SSRF protection)
// ---------------------------------------------------------------------------

function publicOnly(url) {
  if (!url || isPrivateHost(url)) return null;
  return url;
}

// Monitors call their URLs from this server, on a schedule and during tests. A private, loopback or
// link-local address (for example the cloud metadata service 169.254.169.254) would let a chat message
// read this server's own network. So those addresses are refused.
//
// Limits: the check looks at the address as written. A public name that resolves to a private address
// is not caught here.
//
// KEEP IN SYNC: the same code is in "Initialize Case" and "Validate Spec".
//
// The host is read with a pattern, not with the URL class, because the Code node sandbox may not have URL.
// IPv4 forms handled: 2130706433, 0x7f.0.0.1, 0177.0.0.1, 127.1.
// IPv6 forms handled: ::1, 0:0:0:0:0:0:0:1, ::ffff:127.0.0.1, ::ffff:7f00:1.
function isPrivateHost(url) {
  const match = String(url).trim().match(/^https?:\/\/(?:[^@/?#]*@)?(\[[^\]]*\]|[^:/?#]*)/i);
  if (!match) return true;

  let host = match[1];
  try {
    host = decodeURIComponent(host);
  } catch (error) {
    return true;
  }
  host = host.toLowerCase().replace(/^\[|\]$/g, '').replace(/\.$/, '');

  if (!host || host === 'localhost' || /\.(localhost|local|internal|intranet|lan|home\.arpa)$/.test(host)) return true;

  if (host.includes(':')) {
    const groups = expandIpv6(host);
    if (!groups) return true; // not a valid IPv6 address: refuse instead of guessing
    return isPrivateIpv6(groups);
  }

  const ipv4 = readIpv4(host);
  return ipv4 ? isPrivateIpv4(ipv4) : false; // a normal host name is allowed
}

// Takes the first two bytes of an IPv4 address.
// Blocks 0/8, 10/8, 127/8, 169.254/16, 172.16/12, 192.168/16, 100.64/10 and 224.0.0.0 and above.
function isPrivateIpv4([a, b]) {
  return a === 0 || a === 10 || a === 127 || (a === 169 && b === 254) || (a === 172 && b >= 16 && b <= 31) ||
    (a === 192 && b === 168) || (a === 100 && b >= 64 && b <= 127) || a >= 224;
}

// Takes the eight 16-bit groups of an IPv6 address.
function isPrivateIpv6(groups) {
  const first = groups[0];
  const embeddedIpv4 = [groups[6] >> 8, groups[6] & 255];
  const zerosBefore = (count) => groups.slice(0, count).every((group) => group === 0);

  if (zerosBefore(8)) return true; // ::
  if (zerosBefore(7) && groups[7] === 1) return true; // ::1
  if (zerosBefore(5) && groups[5] === 0xffff) return isPrivateIpv4(embeddedIpv4); // ::ffff:a.b.c.d
  if (zerosBefore(6)) return isPrivateIpv4(embeddedIpv4); // ::a.b.c.d (old form)
  if (first === 0x64 && groups[1] === 0xff9b) return isPrivateIpv4(embeddedIpv4); // 64:ff9b::a.b.c.d (NAT64)
  if (first === 0x2002) return isPrivateIpv4([groups[1] >> 8, groups[1] & 255]); // 2002:aabb:: (6to4)

  return (first & 0xfe00) === 0xfc00 // fc00::/7 (unique local)
    || (first & 0xffc0) === 0xfe80 // fe80::/10 (link-local)
    || (first & 0xff00) === 0xff00; // ff00::/8 (multicast)
}

// Returns the eight 16-bit groups of an IPv6 address, or null if the text is not one.
function expandIpv6(host) {
  let text = host.split('%')[0]; // drop a zone id, for example fe80::1%eth0

  // Turn a trailing IPv4 part (::ffff:1.2.3.4) into two hex groups.
  const ipv4Tail = text.match(/^(.*:)(\d+\.\d+\.\d+\.\d+)$/);
  if (ipv4Tail) {
    const bytes = ipv4Tail[2].split('.').map(Number);
    if (bytes.some((byte) => byte > 255)) return null;
    text = ipv4Tail[1] + ((bytes[0] << 8) | bytes[1]).toString(16) + ':' + ((bytes[2] << 8) | bytes[3]).toString(16);
  }

  const halves = text.split('::');
  if (halves.length > 2) return null;

  const toGroups = (part) => (part === '' ? [] : part.split(':'));
  const head = toGroups(halves[0]);
  const tail = halves.length === 2 ? toGroups(halves[1]) : [];
  const missing = 8 - head.length - tail.length;
  if ((halves.length === 1 && missing !== 0) || missing < 0) return null;

  const all = [...head, ...Array(halves.length === 2 ? missing : 0).fill('0'), ...tail];
  if (all.length !== 8 || all.some((group) => !/^[0-9a-f]{1,4}$/.test(group))) return null;

  return all.map((group) => parseInt(group, 16));
}

// Returns the first two bytes if the host is an IPv4 address in any accepted form, otherwise null.
// Accepted forms: dotted decimal, hex (0x7f), octal (0177), and short forms (127.1, 2130706433).
function readIpv4(host) {
  const parts = host.split('.');
  if (parts.length > 4) return null;

  const numbers = [];
  for (const part of parts) {
    let value;
    if (/^0x[0-9a-f]*$/.test(part)) value = parseInt(part.slice(2) || '0', 16);
    else if (/^0[0-7]+$/.test(part)) value = parseInt(part, 8);
    else if (/^\d+$/.test(part)) value = Number(part);
    else return null;
    numbers.push(value);
  }

  // The last number fills all the remaining bytes (so "127.1" means 127.0.0.1).
  const last = numbers.pop();
  if (numbers.some((value) => value > 255) || last >= 256 ** (4 - numbers.length)) return null;

  let total = last;
  numbers.forEach((value, index) => { total += value * 256 ** (3 - index); });
  return [Math.floor(total / 16777216) % 256, Math.floor(total / 65536) % 256];
}

// Decision node. Runs after every section and decides what happens next:
// - run the next section,
// - go back to Build with feedback (the repair loop),
// - or stop and reply.
// It reads state.lastStage to know which section just ran.
//
// Blueprints:
// - Hard validation errors are repaired until attempts run out.
// - Findings (validator warnings and the LLM review) get one repair round.
// - Findings that break the workflow get one more round after that.
// - The best valid draft is always delivered, never discarded.
//
// Stop reasons stored in state.stop:
// stuck, setup, harness, time, needs_endpoint, endpoint_down.

const SETUP_ERROR_PATTERN = /could not be found|unauthori[sz]ed|authoriz|forbidden|api key|\b40[134]\b/i;
const MODEL_BUSY_PATTERN = /busy|too many (concurrent )?requests|rate.?limit|overloaded|at capacity|quota|try again later|\b(429|503)\b/i;
const TEST_BENCH_ERROR_PATTERN = /not active|cannot be executed|could not find|not found|permission|forbidden|access|disabled|not allowed/i;

// An unvalidated draft is only saved when every node is a safe core node.
// KEEP IN SYNC: the same blocked list is in "Validate Blueprint Draft".
const BLOCKED_TYPES = new RegExp(
  '^(n8n-nodes-base\\.(code|aiTransform|function|functionItem|executeCommand|ssh|ftp|git|n8n|readWriteFile|readBinaryFiles?|writeBinaryFile|localFileTrigger|executeWorkflow)' +
  '|@n8n\\/n8n-nodes-langchain\\.(code|toolCode|toolWorkflow|retrieverWorkflow|toolExecutor))$'
);
const CORE_NODE_TYPE = /^(n8n-nodes-base|@n8n\/n8n-nodes-langchain)\.[A-Za-z0-9]+$/;

const request = $('Read Request').first().json;
const result = $json;

// A previous node already built the final reply: pass it through.
if (result.httpStatus) return finish(result.httpStatus, result.body);

if (!result.state) {
  return finish(500, {
    status: 'error',
    verdict: 'Setup problem: a section failed',
    message: 'A section of the workflow failed to run. Check that the workflow is published and the credentials are set.',
    detail: String(result.error?.message || result.error || result.message || ''),
  });
}

const state = result.state;

if (result.llmError) return handleModelError();

const afterStage = {
  understand: afterUnderstand,
  build: afterBuild,
  check: afterCheck,
  review: afterReview,
  test: afterTest,
  deploy: afterDeployError,
}[state.lastStage];

if (!afterStage) return finish(500, { status: 'error', message: 'Unknown stage: ' + state.lastStage });
return afterStage();

// ---------------------------------------------------------------------------
// Model errors
// ---------------------------------------------------------------------------

// The AI model failed in the last section. Use the best earlier result if there is one.
function handleModelError() {
  const modelBusy = MODEL_BUSY_PATTERN.test(result.llmError);

  // An earlier blueprint draft passed validation: deliver it.
  if (state.bestBlueprint) {
    return deliverBlueprint(state, state.bestBlueprint);
  }

  // A monitor repair round failed at the model: keep the best tested draft so far.
  if (state.best) {
    return finish(modelBusy ? 503 : 502, {
      status: 'failed',
      verdict: modelBusy ? 'The AI model is busy' : 'The AI model step failed',
      message: (modelBusy ? 'The AI model became busy during a repair round.' : 'The AI model step failed during a repair round.') +
        ' Here is the best tested attempt so far. Wait a minute, then send your request again.',
      bestAttempt: toBestAttempt(state.best),
      goal: state.goal,
      understood: state.spec,
      attemptsUsed: state.attempt - 1,
      history: state.history,
      detail: result.llmError,
    });
  }

  if (modelBusy) {
    return finish(503, {
      status: 'error',
      verdict: 'The AI model is busy',
      message: 'The AI model is busy or rate limited right now. Nothing is wrong with your request. Wait a minute, then send it again.',
      detail: result.llmError,
    });
  }
  return finish(502, {
    status: 'error',
    verdict: 'The AI model step failed',
    message: 'The AI model step failed after 3 tries.',
    detail: result.llmError,
  });
}

// ---------------------------------------------------------------------------
// What to do after each section
// ---------------------------------------------------------------------------

function afterUnderstand() {
  if (!result.specValid) {
    return finish(422, { status: 'failed', verdict: 'Could not understand the request', errors: result.specErrors, goal: state.goal });
  }
  if (result.route === 'out_of_scope') return finish(422, describeRefusal());

  if (result.route === 'endpoint_problem') {
    return finish(409, {
      status: 'needs_input',
      verdict: state.spec.endpointDown ? 'Your endpoint is down right now' : 'Your endpoint needs a change',
      message: state.spec.endpointProblem,
      understood: state.spec,
      triedUrl: state.userTargetUrl,
      productionCheck: state.spec.endpointProblem,
      goal: state.goal,
    });
  }
  if (result.route === 'needs_endpoint') {
    return finish(409, {
      status: 'needs_input',
      verdict: 'I need the endpoint',
      message: 'I understood what to monitor, but not where. Resend with "targetUrl": "https://..." added.',
      understood: state.spec,
      goal: state.goal,
    });
  }

  // Monitors are tested against the built-in mock. Without it, a monitor cannot be tested.
  if (state.spec.kind !== 'blueprint' && state.mockProblem) {
    return finish(503, {
      status: 'setup_error',
      message: 'The built-in test mock is not reachable, and monitors are tested against it. Publish this workflow, then retry.',
      ...state.mockProblem,
    });
  }
  return runSection('build', { state });
}

// Build returns the parsed draft (or a parse error). The Check section validates it.
function afterBuild() {
  return runSection('check', result);
}

// Invalid draft: back to Build with the errors.
// Valid draft: blueprints go to Review, monitors go to Test.
function afterCheck() {
  if (!result.valid) {
    const feedback = 'Your output was rejected before deployment:\n- ' + result.errors.join('\n- ');
    const nextState = recordAttempt(state, 'invalid_plan', feedback, result.workflow, null);
    if (feedback === state.feedback) {
      nextState.stop = 'stuck'; // the same errors twice in a row
    }
    return retryOrStop(nextState);
  }
  if (state.spec.kind === 'blueprint') return runSection('review', result);
  return runSection('test', result);
}

// Blueprints only. The draft passed validation and was reviewed.
// Its findings (validator warnings and LLM review) get ONE repair round. After that, the best
// draft so far is delivered, with its remaining findings in the setup note.
// Findings that BREAK the workflow (review severity "breaks") get one more round after that,
// if attempts and time allow.
function afterReview() {
  const candidate = {
    workflow: result.workflow,
    findings: result.findings || [],
    breakingFindings: result.breakingFindings || [],
    reviewAvailable: Boolean(result.reviewAvailable),
    accountsToConnect: result.accountsToConnect || [],
    attempt: state.attempt,
  };
  const bestBlueprint = pickBetterBlueprint(state.bestBlueprint, candidate);

  if (candidate.findings.length === 0) return deliverBlueprint(state, candidate);

  const isBreakingRound = state.reviewRepairUsed && candidate.breakingFindings.length > 0 && !state.breakingRepairUsed;
  if (state.reviewRepairUsed && !isBreakingRound) return deliverBlueprint(state, bestBlueprint);

  const fixInstruction = '\nFix these problems and return the complete corrected workflow. Keep everything else as it is.';
  const feedback = isBreakingRound
    ? 'Your corrected workflow still has problems that make it fail or give a wrong result:\n- ' + candidate.breakingFindings.join('\n- ') + fixInstruction
    : 'Your workflow passed validation, but a review found these problems:\n- ' + candidate.findings.join('\n- ') + fixInstruction;

  const nextState = recordAttempt(state, isBreakingRound ? 'breaking_findings' : 'review_findings', feedback, result.workflow, null);
  nextState.reviewRepairUsed = true;
  if (isBreakingRound) nextState.breakingRepairUsed = true;
  nextState.bestBlueprint = bestBlueprint;
  return retryOrStop(nextState);
}

// Monitors only.
function afterTest() {
  if (result.allPassed) return runSection('deploy', result);
  return retryOrStop(recordTestFailure(result));
}

// The deploy section failed: n8n refused to save the workflow.
function afterDeployError() {
  const message = String(result.deployError || 'unknown error');

  // n8n also refused the unvalidated draft: hand the draft over as JSON.
  if (state.unvalidatedTried) return finish(...describeUnsavedDraft(message));

  const nextState = recordAttempt(state, 'api_rejected', 'The n8n API rejected your workflow: ' + message, result.workflow, null);
  nextState.bestBlueprint = null; // the API refused this draft, so it can no longer be the fallback
  if (SETUP_ERROR_PATTERN.test(message)) {
    nextState.stop = 'setup';
    nextState.setupError = message;
  }
  return retryOrStop(nextState);
}

// ---------------------------------------------------------------------------
// Blueprint helpers
// ---------------------------------------------------------------------------

// Fewer breaking findings wins, then fewer findings.
// On a tie the newer draft wins, because it had more feedback.
function pickBetterBlueprint(previousBest, candidate) {
  if (!previousBest) return candidate;
  const breakingCount = (blueprint) => (blueprint.breakingFindings || []).length;
  if (breakingCount(candidate) !== breakingCount(previousBest)) {
    return breakingCount(candidate) < breakingCount(previousBest) ? candidate : previousBest;
  }
  return candidate.findings.length <= previousBest.findings.length ? candidate : previousBest;
}

function deliverBlueprint(currentState, blueprint) {
  return runSection('deploy', {
    state: currentState,
    workflow: blueprint.workflow,
    findings: blueprint.findings,
    reviewAvailable: blueprint.reviewAvailable,
    accountsToConnect: blueprint.accountsToConnect,
    deliveredAttempt: blueprint.attempt,
  });
}

// Last resort for a blueprint: save the last draft as inactive, with its errors in a sticky note.
// Only allowed when the last attempt was an invalid plan and every node is a safe core node.
function canDeliverUnvalidated(finalState) {
  const nodes = finalState.previousWorkflow?.nodes;
  const lastOutcome = (finalState.history[finalState.history.length - 1] || {}).outcome;
  return finalState.spec?.kind === 'blueprint' &&
    finalState.stop !== 'setup' &&
    !finalState.unvalidatedTried &&
    lastOutcome === 'invalid_plan' &&
    Array.isArray(nodes) && nodes.length > 0 &&
    nodes.every((node) => node && typeof node === 'object' && CORE_NODE_TYPE.test(String(node.type)) && !BLOCKED_TYPES.test(String(node.type)));
}

function deliverUnvalidated(finalState) {
  const errors = String(finalState.feedback).split('\n').filter((line) => line.startsWith('- ')).map((line) => line.slice(2));
  const attempt = finalState.attempt - 1; // was counted up for a retry that will not happen
  return runSection('deploy', {
    state: { ...finalState, attempt, unvalidatedTried: true },
    workflow: buildUnvalidatedWorkflow(finalState.previousWorkflow, errors, finalState.spec),
    findings: errors,
    reviewAvailable: false,
    accountsToConnect: finalState.spec.credentials || [],
    deliveredAttempt: attempt,
    notValidated: true,
  });
}

// Repairs the minimum fields n8n needs, and adds a sticky note on top that lists the open problems.
function buildUnvalidatedWorkflow(draft, errors, spec) {
  const nodes = draft.nodes
    .filter((node) => node.type !== 'n8n-nodes-base.stickyNote')
    .map((node, index) => ({
      ...node,
      id: typeof node.id === 'string' && node.id ? node.id : createId(),
      name: String(node.name || 'Node ' + (index + 1)),
      typeVersion: typeof node.typeVersion === 'number' ? node.typeVersion : 1,
      position: Array.isArray(node.position) && node.position.length === 2 ? node.position : [index * 260, 0],
      parameters: node.parameters && typeof node.parameters === 'object' ? node.parameters : {},
    }));

  const left = Math.min(0, ...nodes.map((node) => Number(node.position[0]) || 0));
  const top = Math.min(0, ...nodes.map((node) => Number(node.position[1]) || 0));
  const content = '## ' + spec.service + ' (NOT validated)\n' + (spec.summary || '') +
    '\n\n**This draft did not pass The Alchemist\'s checks.** Fix these problems before running it:\n' +
    errors.map((error) => '- ' + error).join('\n') +
    '\n\n**Then:** connect your accounts, run it once with test data, and activate.';

  nodes.push({
    id: createId(),
    name: 'Setup',
    type: 'n8n-nodes-base.stickyNote',
    typeVersion: 1,
    position: [left, top - 480],
    parameters: { content, height: 440, width: 620, color: 3 },
  });

  const connections = draft.connections && typeof draft.connections === 'object' && !Array.isArray(draft.connections)
    ? draft.connections
    : {};
  return { name: '[Alchemist] ' + spec.service + ' (not validated)', nodes, connections, settings: { executionOrder: 'v1' } };
}

// n8n refused even the unvalidated draft: return it as JSON so the user can import it by hand.
function describeUnsavedDraft(apiMessage) {
  const [, body] = describeStop(state);
  return [422, {
    ...body,
    verdict: 'No valid workflow, and n8n refused to save the last draft',
    message: 'No attempt passed the checks, and the n8n API rejected the last draft (' + apiMessage.slice(0, 200) + '). ' +
      'Here it is as JSON: import it in n8n and fix the problems listed.',
    lastDraft: result.workflow,
  }];
}

// ---------------------------------------------------------------------------
// Monitor test failures
// ---------------------------------------------------------------------------

// Builds the next state after a failed test run. Also decides if the loop must stop early.
function recordTestFailure(testResult) {
  const failures = testResult.checks.filter((check) => !check.pass);
  const score = testResult.passed + '/' + testResult.total;
  const onlyProductionFailed = failures.length === 1 && failures[0].kind === 'smoke';

  let feedback = 'Your workflow deployed but failed ' + failures.length + ' of ' + testResult.total + ' test cases:\n' +
    failures.map((failure) => '- ' + failure.case + ' (' + failure.targetUrl + '): ' + failure.detail).join('\n');
  if (failures.some((failure) => /reason is EMPTY/.test(failure.detail))) {
    feedback += explainEmptyReasons(testResult.workflow);
  }

  const nextState = recordAttempt(testResult.state, 'tests_failed', feedback, testResult.workflow, score);

  // Keep the best scoring draft. A worse score is recorded as a regression.
  const previousBest = testResult.state.best;
  if (!previousBest || testResult.passed >= previousBest.passed) {
    nextState.best = { passed: testResult.passed, score, workflow: testResult.workflow, feedback };
    nextState.regressed = null;
  } else {
    nextState.best = previousBest;
    nextState.regressed = score;
  }
  nextState.triedUrl = testResult.state.spec.targetUrl;

  // A crash in every single test means the test runner is broken, not the draft.
  const firstCrash = failures.map((failure) => failure.detail).find((detail) => detail.startsWith('run crashed'));
  const testBenchBroken = failures.length === testResult.total && Boolean(firstCrash) && TEST_BENCH_ERROR_PATTERN.test(firstCrash);

  if (testBenchBroken) {
    nextState.stop = 'harness';
    nextState.harnessError = firstCrash;
  } else if (onlyProductionFailed) {
    nextState.stop = testResult.state.userTargetUrl ? 'endpoint_down' : 'needs_endpoint';
    nextState.smokeDetail = failures[0].detail;
  } else if (feedback === testResult.state.feedback) {
    nextState.stop = 'stuck'; // the same failures twice in a row
  }
  return nextState;
}

// Extra hint for the model when the test cases report an empty "reason" field.
// The wording is a prompt for the model, so keep it as it is.
function explainEmptyReasons(workflow) {
  const nodes = workflow?.nodes || [];
  const reasonExpression = (nodeName) => {
    const node = nodes.find((item) => item.name === nodeName);
    const fields = node?.parameters?.assignments?.assignments || [];
    return String(fields.find((field) => field.name === 'reason')?.value ?? '(no reason field)');
  };
  return '\nDIAGNOSIS: empty reasons mean the reason expression evaluated to nothing. ' +
    'Your "Result Alert" reason is: ' + reasonExpression('Result Alert') + ' . Your "Result OK" reason is: ' + reasonExpression('Result OK') + ' . ' +
    'Every field you read must exist on the item at that point. After the alert POST, $json is the POST response. ' +
    'Read earlier values with $(\'<node name>\').item.json.<field>.';
}

// ---------------------------------------------------------------------------
// Repair loop and stopping
// ---------------------------------------------------------------------------

// Returns the next state with one more history entry and the feedback for the next build.
function recordAttempt(currentState, outcome, feedback, workflow, score) {
  return {
    ...currentState,
    attempt: currentState.attempt + 1,
    feedback,
    previousWorkflow: workflow,
    history: [...currentState.history, { attempt: currentState.attempt, outcome, score: score || null, feedback }],
  };
}

// Runs another build if attempts and time allow. Otherwise ends with the best result we have.
function retryOrStop(nextState) {
  const attemptsLeft = nextState.attempt <= nextState.maxAttempts;

  if (attemptsLeft && !nextState.stop && isOverTimeBudget(nextState)) {
    nextState.stop = 'time';
  }
  if (attemptsLeft && !nextState.stop) return runSection('build', { state: nextState });

  // Never end with nothing when a valid draft exists.
  if (nextState.bestBlueprint && nextState.stop !== 'setup') {
    return deliverBlueprint({ ...nextState, attempt: nextState.attempt - 1 }, nextState.bestBlueprint);
  }
  if (canDeliverUnvalidated(nextState)) return deliverUnvalidated(nextState);
  return finish(...describeStop(nextState));
}

// Stops the repair loop in time to still send a reply. The workflow timeout in the settings is the
// hard limit behind it, and a run stopped by that timeout cannot reply at all.
function isOverTimeBudget(currentState) {
  const budgetMinutes = Number(currentState.config?.timeBudgetMinutes) || 0;
  if (!budgetMinutes) return false;
  return Date.now() - Date.parse(currentState.startedAt) > budgetMinutes * 60 * 1000;
}

// ---------------------------------------------------------------------------
// Replies
// ---------------------------------------------------------------------------

function describeRefusal() {
  const isBlocked = Boolean(state.spec.blocked);
  return {
    status: isBlocked ? 'refused' : 'out_of_scope',
    verdict: state.spec.verdict || (isBlocked ? 'Refused: suspicious instructions in the request' : 'Out of scope: I only build n8n workflows'),
    message: state.spec.reason,
    whatIBuild: 'n8n workflows, built and checked before I hand them over.',
    goal: state.goal,
  };
}

function toBestAttempt(best) {
  return { score: best.score, remainingIssues: best.feedback, workflow: best.workflow };
}

// Returns [httpStatus, body] for a run that ended without a delivered workflow.
function describeStop(finalState) {
  let httpStatus = 422;
  let body = {
    status: 'failed',
    verdict: 'No working workflow after ' + finalState.maxAttempts + ' attempts',
    lastFeedback: finalState.feedback,
  };

  switch (finalState.stop) {
    case 'needs_endpoint':
      httpStatus = 409;
      body = {
        status: 'needs_input',
        verdict: 'I need a working endpoint',
        message: 'The monitor passed every simulated test, but the endpoint I chose failed the production check. I will not guess again. Resend with "targetUrl": "https://..." added. Redirects are not followed, so if the URL answers HTTP 3xx, use the final URL.',
        triedUrl: finalState.triedUrl,
        productionCheck: finalState.smokeDetail,
      };
      break;
    case 'endpoint_down':
      httpStatus = 424;
      body = {
        status: 'endpoint_down',
        verdict: 'Your endpoint failed the production check',
        message: 'The monitor passed every simulated test, but your targetUrl did not look healthy right now. Check the URL or the service, then retry. Redirects are not followed, so if the URL answers HTTP 3xx, use the final URL.',
        triedUrl: finalState.triedUrl,
        productionCheck: finalState.smokeDetail,
      };
      break;
    case 'setup':
      httpStatus = 500;
      body = {
        status: 'setup_error',
        verdict: 'Setup problem: the n8n API rejected the request',
        message: 'The n8n API rejected the request. This is a setup problem, not a model problem, so I stopped retrying. Check the n8n API credential: Base URL ' + request.base + '/api/v1 and a valid API key.',
        detail: finalState.setupError,
      };
      break;
    case 'harness':
      httpStatus = 500;
      body = {
        status: 'harness_error',
        verdict: 'Setup problem: the test runner is broken',
        message: 'The test runner could not execute the draft at all, so no workflow could have passed. This is a setup problem, not a model problem, so I stopped.',
        detail: finalState.harnessError,
      };
      break;
    case 'time':
      httpStatus = 504;
      body = {
        status: 'failed',
        verdict: 'Stopped: out of time',
        message: 'The build took longer than ' + finalState.config.timeBudgetMinutes + ' minutes, so I stopped before another repair round.',
        lastFeedback: finalState.feedback,
      };
      break;
    case 'stuck':
      body = {
        status: 'stuck',
        verdict: 'Stopped: the same problem came back twice',
        message: 'The model produced the same failure twice in a row, so I stopped to save time and tokens.',
        lastFeedback: finalState.feedback,
      };
      break;
  }

  if (finalState.best) {
    body.bestAttempt = toBestAttempt(finalState.best);
  }
  body = {
    ...body,
    goal: finalState.goal,
    understood: finalState.spec,
    attemptsUsed: finalState.attempt - 1,
    history: finalState.history,
  };
  return [httpStatus, body];
}

// ---------------------------------------------------------------------------
// Output and small helpers
// ---------------------------------------------------------------------------

// Hands the payload to the next section and records which section runs.
function runSection(stage, payload) {
  return [{ json: { ...payload, done: false, stage, state: { ...payload.state, lastStage: stage } } }];
}

function finish(httpStatus, body) {
  return [{ json: { done: true, httpStatus, body } }];
}

// Random v4 style id. Used because the Code node sandbox may not have crypto.randomUUID.
function createId() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => {
    const random = (Math.random() * 16) | 0;
    const value = character === 'x' ? random : (random & 0x3) | 0x8;
    return value.toString(16);
  });
}

// Final node. Every run ends here.
// 1. Turns the reply into chat markdown.
// 2. Remembers an open question (for example "which endpoint?") so the next message
//    in the same chat can answer it.

const EMAIL_NOTE = 'The workflow gets a Gmail node that emails you on every alert. ' +
  'I never handle your credentials. After it is built, open the workflow, connect your Gmail account in the node "Send Alert", then activate it.';
const SLACK_NOTE = 'The workflow gets a Slack node that posts every alert there. ' +
  'After it is built, connect your Slack account in the node "Send Alert", then activate it.';

const result = $json;
const request = $('Read Request').first().json;
const reply = result.body || {};

// How long an open question stays valid. One value, set in "Settings" and passed in by "Read Request".
// Without a value, questions would never expire, so fall back to 30 minutes.
const PENDING_QUESTION_MAX_AGE_MS = Number(request.pendingQuestionLifetimeMs) || 30 * 60 * 1000;

rememberOpenQuestion();

const blocks = [];
switch (reply.status) {
  case 'success':
  case 'draft':
    addBuiltBlocks();
    break;
  case 'needs_input':
    addNeedsInputBlocks();
    break;
  case 'out_of_scope':
    blocks.push('## Out of scope', reply.message, 'What I build: ' + reply.whatIBuild);
    break;
  case 'refused':
    blocks.push('## ' + (reply.verdict || 'Refused'), reply.message);
    break;
  case 'limited':
    blocks.push('## ' + reply.verdict, reply.message);
    break;
  case 'error':
    addErrorBlocks();
    break;
  default:
    addFailureBlocks();
}

addAlertChannelNote();

if (request.continuedFrom) {
  blocks.unshift('_Continuing: "' + request.continuedFrom + '"_');
}

const markdown = blocks.filter(Boolean).join('\n\n');
return [{ json: { httpStatus: 200, body: { output: markdown } } }];

// ---------------------------------------------------------------------------
// Open question memory
// ---------------------------------------------------------------------------

// Stores the goal when the reply asks for input, and clears it after any other reply.
// Also removes questions that are older than the allowed age.
function rememberOpenQuestion() {
  const storage = $getWorkflowStaticData('global');
  storage.pending = storage.pending || {};

  if (reply.status === 'needs_input') {
    storage.pending[request.sessionId] = { goal: reply.goal, ts: Date.now() };
  } else {
    delete storage.pending[request.sessionId];
  }

  for (const [sessionId, question] of Object.entries(storage.pending)) {
    if (Date.now() - question.ts > PENDING_QUESTION_MAX_AGE_MS) {
      delete storage.pending[sessionId];
    }
  }
}

// ---------------------------------------------------------------------------
// Reply sections
// ---------------------------------------------------------------------------

// Status "success" or "draft": the workflow was built.
function addBuiltBlocks() {
  const understood = reply.understood;

  blocks.push('## ' + reply.verdict);

  // The workflow's own name, without the "[Alchemist]" prefix and the "(not validated)" suffix.
  // Falls back to the service name if the reply has no workflow name.
  const madeName = String(reply.workflowName || understood.service)
    .replace(/^\[Alchemist\]\s*/, '')
    .replace(/\s*\(not validated\)$/, '');
  blocks.push('I made **' + madeName + '** for you. ' + understood.summary);

  if (reply.notValidated && reply.message) {
    blocks.push('**' + reply.message + '**');
  }

  if (understood.checks && understood.checks.length > 0) {
    const endpoint = reply.production ? '\n\n**Endpoint:** ' + reply.production.targetUrl : '';
    blocks.push('**Checks:** ' + listCheckNames(understood) + endpoint);
  }
  for (const note of understood.notes || []) {
    blocks.push('**Note:** ' + note);
  }
  if (understood.steps && understood.steps.length > 0) {
    blocks.push('**Plan:**\n' + toBulletList(understood.steps));
  }

  // Test results, or (when nothing was fired) the static checks.
  if (reply.tests && reply.tests.length > 0) {
    const passedCount = reply.tests.filter((test) => test.pass).length;
    const testLines = reply.tests.map((test) => '- ' + (test.pass ? '✅ ' : '❌ ') + test.case + ': ' + shorten(test.reason));
    blocks.push('**Tested: ' + passedCount + '/' + reply.tests.length + ' passed**\n' + testLines.join('\n'));
  } else if (reply.checked) {
    const checkedLines = reply.checked.map((item) => '- ✅ ' + item);
    blocks.push('**Checked:**\n' + checkedLines.join('\n') +
      '\n\n_Not fired yet: run it once with test data before you trust it live._');
  }

  if (reply.openFindings && reply.openFindings.length > 0) {
    const title = reply.notValidated ? '**Fix before running:**' : '**Review before running:**';
    const icon = reply.notValidated ? '❌ ' : '⚠️ ';
    blocks.push(title + '\n' + reply.openFindings.map((finding) => '- ' + icon + shorten(finding, 300)).join('\n'));
  }

  blocks.push('**Workflow:** [' + reply.workflowUrl + '](' + reply.workflowUrl + ') (' + (reply.active ? 'active' : 'inactive') + ')');
  for (const step of reply.nextSteps || []) {
    blocks.push('_' + step + '_');
  }
  blocks.push('_' + reply.attemptsUsed + ' attempt(s), ' + reply.durationSeconds + ' s_');
}

// Status "needs_input": the monitor has no usable endpoint yet.
function addNeedsInputBlocks() {
  const understood = reply.understood || {};

  blocks.push('## ' + (reply.verdict || 'I need the endpoint'));
  blocks.push('I understood: **' + (understood.service || 'a monitor') + '**. ' + (understood.summary || ''));

  if (understood.endpointProblem) {
    blocks.push(understood.endpointProblem);
  } else if (reply.triedUrl) {
    blocks.push('I tried ' + reply.triedUrl + ', but it failed the production check: ' + shorten(reply.productionCheck));
  }

  if (!understood.endpointDown) {
    blocks.push('Reply with the URL to check, for example `https://status.example.com`.');
  }
}

// Status "error": either an invalid request (HTTP 400, shown as a welcome text) or a failure on our side.
function addErrorBlocks() {
  if (result.httpStatus === 400) {
    blocks.push('## Welcome to The Alchemist');
    blocks.push('Tell me what you want automated, in one sentence. I build it, test and check it as hard as I can before handing it to you.');
    blocks.push('Try:\n- Alert me on any GitHub incident\n- Tell me if Wikipedia breaks or gets slower than 2 seconds\n- Create a form that asks name and age and says thank you');
    blocks.push('Add a Slack or webhook.site URL to your message and I will also activate it.');
    return;
  }

  blocks.push('## ' + (reply.verdict || 'Something broke on my side'));
  const detail = reply.detail ? ' (' + shorten(reply.detail) + ')' : '';
  blocks.push((reply.message || 'Unknown error.') + detail);
}

// Any other status: the build did not finish. Show what we know.
function addFailureBlocks() {
  blocks.push('## ' + (reply.verdict || 'Could not finish'));
  if (reply.message) {
    blocks.push(reply.message);
  }
  for (const note of reply.understood?.notes || []) {
    blocks.push('**Note:** ' + note);
  }
  if (reply.mockUrl) {
    blocks.push('Tried: `' + reply.mockUrl + '` (' + (reply.checkResult || 'no answer') + ')');
  }
  if (reply.errors) {
    blocks.push(reply.errors.slice(0, 5).map((error) => '- ' + shorten(error)).join('\n'));
  }

  if (reply.lastFeedback && !reply.bestAttempt && !reply.errors) {
    const lines = bulletLines(reply.lastFeedback, 6);
    if (lines.length > 0) {
      blocks.push('Last attempt was rejected for:\n' + lines.join('\n'));
    }
  }
  if (reply.lastDraft) {
    blocks.push('Last draft (import it in n8n: paste on the canvas, or save as a .json file and use Import from File):\n' +
      '```json\n' + JSON.stringify(reply.lastDraft, null, 2) + '\n```');
  }
  if (reply.bestAttempt) {
    const lines = bulletLines(reply.bestAttempt.remainingIssues, 6);
    blocks.push('Best attempt: **' + reply.bestAttempt.score + '**. Remaining issues:\n' + lines.join('\n'));
  }
}

// Tells the user to connect their own Gmail or Slack account, because the workflow never holds credentials.
// Skipped for success replies and for blueprints (those reply texts already cover it).
function addAlertChannelNote() {
  const mentionsAlertTarget = request.email || request.slackChannel || /\b\S+@\S+\.\w+/.test(request.continuedFrom || '');
  const isBlueprint = reply.kind === 'blueprint' || reply.understood?.kind === 'blueprint';
  if (!mentionsAlertTarget || reply.status === 'success' || isBlueprint) return;

  if (request.slackChannel) {
    blocks.push('**Slack ' + request.slackChannel + ':** ' + SLACK_NOTE);
  } else {
    blocks.push('**Email to ' + (request.email || 'your address') + ':** ' + EMAIL_NOTE);
  }
}

// ---------------------------------------------------------------------------
// Text helpers
// ---------------------------------------------------------------------------

function listCheckNames(understood) {
  const checks = understood?.checks || [];
  return checks.map((check) => (typeof check === 'string' ? check : check.type)).join(', ');
}

function toBulletList(items) {
  return items.map((item) => '- ' + item).join('\n');
}

// Takes the lines that start with "- " from a multi-line text, shortened, up to a maximum count.
function bulletLines(text, max) {
  return String(text)
    .split('\n')
    .filter((line) => line.startsWith('- '))
    .slice(0, max)
    .map((line) => shorten(line));
}

// Removes the internal mock URL from a message, then cuts it to the limit.
// The cut happens at the last space, never inside a word.
function shorten(text, limit = 220) {
  const clean = String(text ?? '').replace(/ from \S*alchemist-mock\S*/g, '');
  if (clean.length <= limit) return clean;

  const cut = clean.slice(0, limit);
  const lastSpace = cut.lastIndexOf(' ');
  const trimmed = lastSpace > limit / 2 ? cut.slice(0, lastSpace) : cut;
  return trimmed.replace(/[\s,.;:]+$/, '') + '…';
}

// Builds the prompt for the Understand step.
// It turns the user's goal into a spec: a "monitor", a "blueprint", or out of scope.
// If the user gave an endpoint, the prompt also includes a short summary of what that endpoint answered.

const SPEC_INSTRUCTIONS = `You turn a request into a JSON spec for an automatic n8n workflow builder. There are two kinds of spec.

KIND "monitor": anything about a service being down, broken, degraded, slow, having an incident or an outage, or a page or API not working. "Alert me on any <service> incident" is a monitor: check that service's official status page API with a jsonField check. Monitors are fully tested before delivery.
KIND "blueprint": ANY other automation (forms, webhooks, reports, digests, emails, syncs between apps, AI assistants, data processing...). A blueprint is a clean, validated starting point the user will finish; it is not tested.
OUT OF SCOPE only: requests that are not an automation at all (an essay, a question, a joke) or that would cause harm.

SPEC SHAPE (monitor):
{"outOfScope": false, "kind": "monitor", "service": "<short service name>", "targetUrl": "<https URL or null>", "checks": [ ... ], "summary": "<one sentence: what counts as unhealthy>"}

SPEC SHAPE (blueprint):
{"outOfScope": false, "kind": "blueprint", "service": "<short name for the workflow, 2 to 5 words>", "summary": "<one sentence: what it does>", "trigger": "<form | webhook | schedule | chat | manual | app event>", "steps": ["<step 1>", "<step 2>", "..."], "credentials": ["<accounts the user must connect, e.g. Gmail>"]}

SPEC SHAPE (out of scope):
{"outOfScope": true, "reason": "<one sentence why>"}

The rules below about targetUrl and CHECKS apply to monitors only.

targetUrl rules:
- A real, public, documented endpoint that answers GET without authentication.
- Prefer official status or health endpoints (for example a status page API like .../api/v2/status.json) over joke or novelty endpoints.
- Use the final URL: https, the exact host (with or without www) and the exact path that answer directly with 2xx. The monitor does not follow redirects, so a URL that answers 3xx fails.
- If the request is about something private or unnamed ("my website", "our API", "the shop"), use null. Never invent hostnames.
- If the user gave an endpoint, it is the targetUrl, and the checks must fit what that endpoint answers (see what it answered, below the request). A status page rule does not apply to a user endpoint that is not a status page.
- If an endpoint is given and the request names no specific service, name the service after the domain (for example "automiq.fi").

CHECKS (the HTTP status check is always included; add only what the request needs, each type at most once):
{"type": "jsonField", "path": "a.b.c", "equals": <string|number|boolean>}  healthy only when that JSON field equals the value. Use it when the endpoint reports health in a field (status pages).
{"type": "keyword", "text": "<2-100 chars, no quotes>"}  healthy only when the response body contains this text. Use it for web pages that can return 200 while broken.
{"type": "latency", "maxMs": <1+1234567890>}  healthy only when the response arrives within maxMs. Use it when the request mentions speed or slowness.
{"type": "rateLimit"}  HTTP 429 means rate limited, not down. Use it for public APIs with strict rate limits (GitHub API, Twitter/X, Reddit and similar).

EXAMPLES:
Request: Alert me when Wikipedia is down
<spec>{"outOfScope": false, "kind": "monitor", "service": "Wikipedia", "targetUrl": "https://en.wikipedia.org/wiki/Main_Page", "checks": [{"type": "keyword", "text": "Wikipedia"}], "summary": "Unhealthy when the main page fails or no longer shows the word Wikipedia."}</spec>

Request: Notify me whenever Bitbucket has an incident
